// The broken pair, for reference:
//
//   tilemap.hpp:  int loaded_tiles = 0;                  // definition!
//                 int tile_index(int x, int y) { ... }   // definition!
//                 int tile_count();
//   tilemap.cpp:  (nothing)
//
//   Two including .cpp files -> `multiple definition of loaded_tiles` and
//   of tile_index at LINK time, plus `undefined reference to tile_count`.
//   Neither is a compile error: every TU had a usable declaration, and the
//   disagreement only exists once the linker sees all the objects.

// ---------- tilemap.hpp ----------
#ifndef TILEMAP_TILEMAP_HPP
#define TILEMAP_TILEMAP_HPP

// Definition of a class: one per translation unit is fine, because the ODR
// allows repeated identical class definitions.
struct TileMap {
    int columns;
    int rows;
};

// Definition of an inline function: also allowed once per translation unit,
// and the toolchain emits it as a weak/COMDAT symbol so the linker keeps one.
// Small and hot, so putting it in the header is the point.
inline int tile_index(const TileMap& map, int x, int y) {
    return y * map.columns + x;
}

// Declaration only. Exactly one translation unit may define it; users get
// an undefined-reference error if none does.
int tile_count(const TileMap& map);

// Declaration only: `extern` with no initialiser allocates nothing here.
extern int loaded_tiles;

// Definition, but of an inline variable (C++17): every including translation
// unit names the same object rather than getting a private copy.
inline constexpr int max_columns = 4096;

#endif

// ---------- tilemap.cpp ----------
// The program's one definition of loaded_tiles.
int loaded_tiles = 0;

// The program's one definition of tile_count. Not inline: changing its body
// recompiles this file only.
int tile_count(const TileMap& map) {
    loaded_tiles += map.columns * map.rows;
    return map.columns * map.rows;
}

#include <cstddef>

// The macros being retired, and what each one gets wrong:
//
//   #define WRAPPED(c, s) ((c) + (s) % COLUMNS)
//       Every parameter is parenthesised and it is still wrong: the whole
//       expansion is not, so `%` binds tighter than the `+` the author meant
//       to wrap. WRAPPED(3, 5) yields 4, not 0.
//
//   #define PICK_LARGER(a, b) ((a) > (b) ? (a) : (b))
//       Correct precedence, but `a` appears twice, so PICK_LARGER(next(), 0)
//       calls next() twice. A macro has no parameter objects to evaluate into.

inline constexpr int columns = 4;

// One parameter object per argument: each argument is evaluated exactly once,
// and the result is an expression the compiler parses, not text it pastes.
constexpr int wrapped(int column, int step) {
    return (column + step) % columns;
}

template<class T>
constexpr const T& pick_larger(const T& left, const T& right) {
    return left < right ? right : left;
}

// Conditional compilation is the job the preprocessor keeps: there is no
// language-level way to select this before translation.
#ifdef NDEBUG
inline constexpr bool tile_checks_enabled = false;
#else
inline constexpr bool tile_checks_enabled = true;
#endif

// The contract, executable: one call, and the precedence is the author's.
constexpr int probe(int& calls) {
    ++calls;
    return 5;
}

constexpr bool behaves() {
    int calls = 0;
    const int result = wrapped(3, probe(calls));
    return result == 0 && calls == 1;
}

static_assert(behaves());

// ---------- units.hpp ----------
#ifndef UNITS_UNITS_HPP
#define UNITS_UNITS_HPP

#include <cstdint>

// DEFINITION, repeatable per translation unit. Every copy must be the same
// definition; adding a member in one header and not another is the classic
// silent ODR violation, because the mangled names still match.
struct Length {
    std::int64_t millimetres;
};

// DEFINITION of an inline variable (C++17). One entity for the whole program,
// usable as an array bound or template argument in every translation unit.
inline constexpr std::int64_t millimetres_per_metre = 1'000;

// DEFINITION, repeatable. `static constexpr` members have been implicitly
// inline since C++17, so taking the address below needs no out-of-class
// definition — before C++17 that line was an odr-use and an undefined
// reference waiting to happen.
struct Tolerance {
    static constexpr std::int64_t default_micrometres = 50;
};

// DEFINITION of an inline function, repeatable. "Matching tokens" is stricter
// than "obviously equivalent": another header spelling this body
// `return Length{metres * millimetres_per_metre};` with the operands swapped
// would be an ODR violation even though the arithmetic agrees.
inline Length metres(std::int64_t count) {
    return Length{count * millimetres_per_metre};
}

// DECLARATION only. Exactly one definition may exist in the whole program;
// with none, the compiler is satisfied and the linker is not.
std::int64_t conversions_performed();

// DECLARATION only: extern without an initialiser allocates no storage.
extern std::int64_t conversion_budget;

#endif

// ---------- units.cpp ----------
// DEFINITIONS. One each, in one translation unit.
std::int64_t conversion_budget = 1'000'000;

std::int64_t conversions_performed() {
    return millimetres_per_metre;
}

// Odr-use of the static constexpr member: binding a reference or taking an
// address needs the entity to exist, not merely its value.
const std::int64_t* tolerance_address = &Tolerance::default_micrometres;

#include <cstddef>

// A per-process counter that no other translation unit can reach by name,
// and a per-type counter, in one file. All three properties differ.

namespace {

// Storage duration: static. Scope: namespace (this file's anonymous one).
// Linkage: INTERNAL — another .cpp may spell `issued_total` too and it will
// be a different object. This is the right tool: unlike namespace-scope
// `static`, an anonymous namespace can also localise a type.
std::size_t issued_total = 0;

struct Bookkeeping {
    std::size_t peak;
};

Bookkeeping bookkeeping{0};

}  // namespace

// Storage duration: static. Scope: namespace. Linkage: EXTERNAL — a header
// declaring `extern std::size_t handles_outstanding;` lets any translation
// unit denote this very object.
std::size_t handles_outstanding = 0;

// One counter per instantiation. The local static has static storage
// duration, block scope and NO linkage; the template gives each Device its
// own object, and the ODR's template allowance makes every translation unit
// that instantiates next_handle<Sensor> share one of them.
template<class Device>
std::size_t next_handle() {
    static std::size_t issued = 0;
    ++issued_total;
    ++handles_outstanding;
    if (issued_total > bookkeeping.peak) bookkeeping.peak = issued_total;
    return ++issued;
}

struct Sensor {};
struct Actuator {};

// Functions have no storage duration at all — that classification applies to
// objects and references. This one has external linkage; the anonymous
// namespace above is what internal linkage looks like.
std::size_t issue_pair() {
    return next_handle<Sensor>() + next_handle<Actuator>();
}

#include <cstddef>
#include <vector>

// Another .cpp in this project also defines a `Node` and a `depth` helper at
// namespace scope. Two definitions of the same externally linked class in one
// program is an ODR violation: the mangled names match, so the link commonly
// succeeds, and whichever body the linker kept then runs against the other
// file's layout. No diagnostic is required.

namespace {

// Internal linkage for the TYPE as well as the function. Namespace-scope
// `static` would localise depth_of but has no way to localise Node — that is
// the reason the rule names anonymous namespaces specifically.
struct Node {
    int payload;
    std::size_t children;
};

std::size_t depth_of(const std::vector<Node>& nodes) {
    std::size_t deepest = 0;
    for (const Node& node : nodes) {
        if (node.children > deepest) deepest = node.children;
    }
    return deepest;
}

}  // namespace

// The only name this translation unit publishes: external linkage, declared
// in the header, and it deliberately does not mention Node in its signature —
// an internal-linkage type must not leak into an externally linked interface.
std::size_t tree_depth(const int* payloads, std::size_t count) {
    std::vector<Node> nodes;
    nodes.reserve(count);
    for (std::size_t i = 0; i < count; ++i) {
        nodes.push_back(Node{payloads[i], i});
    }
    return depth_of(nodes);
}

