// ---------- sampler_c.h (also compiled by C consumers) ----------
#ifdef __cplusplus
extern "C" {
#endif

// Opaque handle: the concrete layout never crosses the boundary.
typedef struct sampler sampler;

// The callback is a plain C function pointer plus a void* for user state.
// A std::function or a lambda with captures cannot cross here, and C has no
// overloading, so each of these names must be unique on its own.
typedef void (*sampler_on_frame)(const float* frames, size_t count,
                                 void* user_data);

sampler* sampler_create(unsigned rate);
int sampler_set_callback(sampler* handle, sampler_on_frame callback,
                         void* user_data);
int sampler_push(sampler* handle, const float* frames, size_t count);
void sampler_destroy(sampler* handle);

#ifdef __cplusplus
}
#endif

// ---------- sampler_c.cpp ----------
struct sampler {
    unsigned rate;
    std::vector<float> pending;
    sampler_on_frame callback = nullptr;
    void* user_data = nullptr;
};

extern "C" sampler* sampler_create(unsigned rate) {
    return new sampler{rate, {}, nullptr, nullptr};
}

extern "C" int sampler_set_callback(sampler* handle, sampler_on_frame callback,
                                    void* user_data) {
    if (handle == nullptr) return -1;  // errors are return codes, not exceptions
    handle->callback = callback;
    handle->user_data = user_data;
    return 0;
}

extern "C" int sampler_push(sampler* handle, const float* frames,
                            size_t count) {
    if (handle == nullptr || frames == nullptr) return -1;
    handle->pending.assign(frames, frames + count);
    if (handle->callback != nullptr) {
        handle->callback(handle->pending.data(), handle->pending.size(),
                         handle->user_data);
    }
    return 0;
}

// The library that created the object also destroys it, so allocation and
// runtime-library ownership never cross the boundary inconsistently.
extern "C" void sampler_destroy(sampler* handle) {
    delete handle;
}

