#pragma once

#include <cstddef>
#include <memory>
#include <string_view>

class Tokenizer {
public:
    explicit Tokenizer(std::string_view grammar);

    // Declared here, DEFINED in the source file. Destroying a
    // unique_ptr<Impl> instantiates delete on Impl, which needs a complete
    // type — and Impl is deliberately incomplete in this header. `= default`
    // written here would not compile.
    ~Tokenizer();

    Tokenizer(Tokenizer&&) noexcept;
    Tokenizer& operator=(Tokenizer&&) noexcept;

    Tokenizer(const Tokenizer&) = delete;
    Tokenizer& operator=(const Tokenizer&) = delete;

    std::size_t feed(std::string_view text);

private:
    class Impl;                   // declaration only
    std::unique_ptr<Impl> impl_;  // sizeof(Tokenizer) never moves
};

// ---------- tokenizer.cpp ----------
#include <string>
#include <utility>
#include <vector>

class Tokenizer::Impl {
public:
    explicit Impl(std::string_view grammar) : grammar_(grammar) {}

    std::size_t feed(std::string_view text) {
        tokens_.emplace_back(text);
        // Adding a member here recompiles this file only, and does not change
        // sizeof(Tokenizer) for anyone who already compiled against the header.
        ++accepted_;
        return tokens_.size();
    }

private:
    std::string grammar_;
    std::vector<std::string> tokens_;
    std::size_t accepted_ = 0;
};

Tokenizer::Tokenizer(std::string_view grammar)
    : impl_(std::make_unique<Impl>(grammar)) {}

// Defined where Impl is complete; `= default` is enough here.
Tokenizer::~Tokenizer() = default;
Tokenizer::Tokenizer(Tokenizer&&) noexcept = default;
Tokenizer& Tokenizer::operator=(Tokenizer&&) noexcept = default;

std::size_t Tokenizer::feed(std::string_view text) {
    return impl_->feed(text);
}

// The contract, checkable without a linker: the public class is one pointer.
static_assert(sizeof(Tokenizer) == sizeof(void*));

